$string['panel_isthis_bridge'] = 'Uma ponte traz para o Eguahe o que chega por outra ferramenta (os anúncios do Google ou da Meta, a caixa de admissões ou um formulário que a escola já usa), para que cada família tenha a sua ficha e lhe respondam a partir da caixa de entrada.';
$string['panel_isthis_entries'] = 'Uma entrada é um sítio por onde chegam as famílias: o formulário do site da escola, um QR num cartaz, a caixa de admissões ou os anúncios do Google ou da Meta. Cada família que chega por uma delas conta como uma chegada, e aqui vê-se qual traz mais.';
$string['panel_isthis_forecast'] = 'A previsão calcula, com as crianças da zona e o que aconteceu noutras campanhas, quantas famílias poderiam pedir vaga em cada ano. Não é uma promessa: é uma margem razoável para preparar vagas e turmas.';
$string['panel_isthis_kit'] = 'O kit é o que se partilha para que as famílias se inscrevam num evento: a ligação, o QR para o cartaz, os cartazes e os textos para as redes e o canal, prontos a copiar.';
$string['panel_isthis_labels'] = 'As etiquetas da mochila levam o nome de cada criança escrito à mão, como na sua página. Imprimem-se em folhas de autocolantes e entregam-se à porta do evento.';
$string['panel_isthis_metrics'] = 'Os números contam como vai a campanha: quantas famílias perguntam, quantas vêm e quantas se matriculam, por onde chegam e quantas vagas restam. Cada número leva por baixo o que conta.';
$string['panel_isthis_renewal'] = 'Aqui pergunta-se às famílias que já estão na escola se os filhos continuam no próximo ano letivo. Respondem na sua página com um toque, e vê-se, ano a ano, quem continua, quem não e quem ainda não sabe: assim sabe-se quantas vagas restam para alunos novos.';
