$string['panel_voice_channel'] = 'Por canal';
$string['panel_voice_channel_def'] = 'De onde vêm de verdade: o primeiro contacto medido de cada família, nunca a jornada ou o formulário por onde entrou, e também com as que se perderam. Primeiro, os canais da própria escola (o seu site, os motores de busca, os assistentes de IA, o seu perfil do Google, as suas redes, os seus e-mails e mensagens, e o passa-palavra); depois, a publicidade; depois, outros caminhos (impressos e QR, outros sites, sem passar pelo site), e no fim o que não se mediu. Cada canal, com até onde chegaram as suas famílias e quem são: as novas de verdade, as que já eram da escola (que não contam no resto dos números), as que já tiveram filhos nela e as de antigos alunos.';
